arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Content-Type: application/json' -H "Authorization: <TOKEN>" -d '{"query":"{ issues(first: 50) { nodes { id identifier title url team { key name } projects { nodes { name } } labelNames } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for i in d['data']['issues']['nodes']:
    if 'SSO' in i['title']:
        t=i.get('team') or {}
        ps=[p['name'] for p in i['projects']['nodes']]
        print(i['identifier'],'| team:',t.get('key'),t.get('name'),'| projects:',ps,'| labels:',i.get('labelNames'),'|',i['url'])
"

